# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

def check_owner(student: Student, marks: List[Mark]) -> None:
    """Refuse marks that belong to somebody else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id} given with {student.student_id}")

def render_notice(student: Student, days: List) -> str:
    """Lay out the notice text for the given absent days."""
    name = f"{student.first_name} {student.last_name}"
    lines = [f"{name} was absent on {len(days)} day(s) in total.", "Dates missed:"]
    lines.extend(f"- {day.isoformat()}" for day in days)
    return "\n".join(lines)

# ---
def build_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Write a short notice naming the student, the count and the dates."""
    mark_list = list(marks)
    check_owner(student, mark_list)
    days = sorted(set(days_missed(mark_list)))
    if not days:
        raise ValueError(f"no absences to report for {student.student_id}")
    return render_notice(student, days)
